  ],
  "next_game": [
    {
      "title": "Проверка условий перед активацией BKB",
      "action": "Перед использованием BKB в игре убедитесь, что контроль над вами снят или вы находитесь в безопасной зоне.",
      "measure": "Проверьте, не умерли ли вы в течение 10 секунд после активации BKB в следующих играх.",
      "evidence_ids": ["r1a.use", "r1a.death"]
    }
  ]
}

